                    m0.z = fmaxf(m0.z, __ldg(p + 2));
                    m0.w = fmaxf(m0.w, __ldg(p + 3));
                    m1.x = fmaxf(m1.x, __ldg(p + 4));
                    m1.y = fmaxf(m1.y, __ldg(p + 5));
                    m1.z = fmaxf(m1.z, __ldg(p + 6));
